/**
 * TS≡Python parity harness — runs the compiled TypeScript kernels against the
 * golden fixtures generated by the Python port. Proves both ports emit
 * bit-identical output (the whole point of effects-core). Requires `npm run
 * build` first (compiles src → dist). Exits non-zero on any mismatch.
 */

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const reg = await import(join(here, "..", "dist", "registry.js"));
const ff = await import(join(here, "..", "dist", "ffexpr.js"));

const golden = JSON.parse(
  readFileSync(join(here, "fixtures", "golden", "kernels.json"), "utf8"),
);

let failures = 0;
let checks = 0;
for (const [id, spec] of Object.entries(golden)) {
  if (reg.categoryOf(id) !== spec.category) {
    console.error(`category mismatch ${id}: ${reg.categoryOf(id)} != ${spec.category}`);
    failures++;
  }
  for (const sample of spec.samples) {
    const got = reg.apply(id, sample.t);
    for (const [k, v] of Object.entries(sample.out)) {
      checks++;
      if (got[k] !== v) {
        console.error(`MISMATCH ${id}@t=${sample.t}.${k}: TS ${got[k]} != PY ${v}`);
        failures++;
      }
    }
  }
}

// ffexpr bridge: the FFmpeg expression strings must evaluate to the exact kernel
// values at the same normalized time (frame-accurate parity with vfx.py's render
// path). Mirrors packages/effects-core/test/test_ffexpr.py.
const round9 = (v) => Math.round(v * 1e9) / 1e9;
const ffChecks = [
  ["push-in", (t) => ({ zoom: ff.evaluate(ff.pushInZoomExpr("t"), { t }) })],
  [
    "ken-burns",
    (t) => {
      const e = ff.kenBurnsExpr("t");
      return {
        zoom: ff.evaluate(e.zoom, { t }),
        x: ff.evaluate(e.x, { t }),
        y: ff.evaluate(e.y, { t }),
      };
    },
  ],
  [
    "handheld",
    (t) => {
      const e = ff.handheldExpr("t");
      return {
        dx: ff.evaluate(e.dx, { t }),
        dy: ff.evaluate(e.dy, { t }),
        rot: ff.evaluate(e.rot, { t }),
      };
    },
  ],
];
for (const [id, build] of ffChecks) {
  for (const sample of golden[id].samples) {
    const got = build(sample.t);
    for (const [k, v] of Object.entries(sample.out)) {
      checks++;
      if (round9(got[k]) !== v) {
        console.error(`FFEXPR MISMATCH ${id}@t=${sample.t}.${k}: ${round9(got[k])} != ${v}`);
        failures++;
      }
    }
  }
}

if (failures) {
  console.error(`\neffects-core parity FAILED: ${failures} mismatch(es)`);
  process.exit(1);
}
console.log(`effects-core TS≡Python parity OK (${checks} values across ${Object.keys(golden).length} kernels)`);
